// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/// @title MLInferenceOracle - On-chain ML inference result aggregation
/// @notice Aggregates inference results from off-chain K8s workers with signal-based coordination
contract MLInferenceOracle is Ownable, ReentrancyGuard {

    enum RequestState { Pending, Processing, Completed, Cancelled }

    struct InferenceRequest {
        address requester;
        bytes32 modelHash;
        bytes inputData;
        RequestState state;
        uint256 timestamp;
        uint256 deadline;
        uint256 stake;
    }

    struct WorkerSignal {
        address worker;
        bytes32 resultHash;
        uint256 confidence;
        uint256 signalTimestamp;
        bool finalized;
    }

    mapping(uint256 => InferenceRequest) public requests;
    mapping(uint256 => WorkerSignal[]) public signals;
    mapping(uint256 => mapping(address => bool)) public hasSignaled;
    mapping(address => bool) public registeredWorkers;
    mapping(address => uint256) public workerStakes;
    mapping(uint256 => bool) public requestSettled;

    uint256 public nextRequestId;
    uint256 public constant MIN_SIGNALS = 3;
    uint256 public constant SIGNAL_WINDOW = 30; // blocks
    uint256 public constant MIN_STAKE = 0.1 ether;

    event InferenceRequested(uint256 indexed requestId, address requester, bytes32 modelHash);
    event SignalSubmitted(uint256 indexed requestId, address worker, bytes32 resultHash);
    event InferenceFinalized(uint256 indexed requestId, bytes32 consensusResult);
    event WorkerSlashed(address worker, uint256 amount);

    modifier onlyRegisteredWorker() {
        require(registeredWorkers[msg.sender], "Not registered worker");
        require(workerStakes[msg.sender] >= MIN_STAKE, "Insufficient stake");
        _;
    }

    function registerWorker() external payable {
        require(msg.value >= MIN_STAKE, "Minimum stake required");
        registeredWorkers[msg.sender] = true;
        workerStakes[msg.sender] += msg.value;
    }

    function requestInference(
        bytes32 modelHash,
        bytes calldata inputData,
        uint256 deadline
    ) external payable returns (uint256) {
        require(msg.value > 0, "Payment required");
        require(deadline > block.number, "Invalid deadline");

        uint256 requestId = nextRequestId++;
        requests[requestId] = InferenceRequest({
            requester: msg.sender,
            modelHash: modelHash,
            inputData: inputData,
            state: RequestState.Pending,
            timestamp: block.timestamp,
            deadline: deadline,
            stake: msg.value
        });

        emit InferenceRequested(requestId, msg.sender, modelHash);
        return requestId;
    }

    /// @notice Workers submit inference signals - mimics POSIX signal handler pattern
    /// @dev The signal submission and state transition are atomically coupled
    function submitSignal(
        uint256 requestId,
        bytes32 resultHash,
        uint256 confidence
    ) external onlyRegisteredWorker nonReentrant {
        InferenceRequest storage req = requests[requestId];
        require(req.state == RequestState.Pending || req.state == RequestState.Processing, "Invalid state");
        require(block.number <= req.deadline, "Past deadline");
        require(!hasSignaled[requestId][msg.sender], "Already signaled");

        // Transition to Processing on first signal
        if (req.state == RequestState.Pending) {
            req.state = RequestState.Processing;
        }

        hasSignaled[requestId][msg.sender] = true;
        signals[requestId].push(WorkerSignal({
            worker: msg.sender,
            resultHash: resultHash,
            confidence: confidence,
            signalTimestamp: block.timestamp,
            finalized: false
        }));

        emit SignalSubmitted(requestId, msg.sender, resultHash);

        // Auto-finalize when enough signals received
        if (signals[requestId].length >= MIN_SIGNALS) {
            _tryFinalize(requestId);
        }
    }

    /// @notice Finalization with consensus check
    /// @dev Settlement flag checked BEFORE state modification - atomic
    function _tryFinalize(uint256 requestId) internal {
        InferenceRequest storage req = requests[requestId];

        // Settlement flag checked first - prevents any race
        if (requestSettled[requestId]) {
            return;
        }

        // Mark as settled BEFORE any external calls or state that could be observed
        requestSettled[requestId] = true;
        req.state = RequestState.Completed;

        bytes32 consensusResult = _computeConsensus(requestId);

        // Settlement: distribute rewards
        _distributeRewards(requestId, consensusResult);

        emit InferenceFinalized(requestId, consensusResult);
    }

    /// @notice Cancel and reclaim - properly checks settlement atomically
    function cancelRequest(uint256 requestId) external nonReentrant {
        InferenceRequest storage req = requests[requestId];
        require(msg.sender == req.requester, "Not requester");
        require(block.number > req.deadline, "Deadline not passed");
        require(!requestSettled[requestId], "Already settled");
        require(req.state != RequestState.Completed, "Already completed");
        require(req.state != RequestState.Cancelled, "Already cancelled");

        req.state = RequestState.Cancelled;
        requestSettled[requestId] = true;

        (bool success, ) = payable(msg.sender).call{value: req.stake}("");
        require(success, "Transfer failed");
    }

    function _computeConsensus(uint256 requestId) internal view returns (bytes32) {
        WorkerSignal[] storage sigs = signals[requestId];

        bytes32 bestResult;
        uint256 bestCount;

        for (uint256 i = 0; i < sigs.length; i++) {
            // Simple majority vote weighted by confidence
            bytes32 h = sigs[i].resultHash;
            // Count occurrences
            uint256 count = 0;
            for (uint256 j = 0; j <= i; j++) {
                if (sigs[j].resultHash == h) count++;
            }
            if (count > bestCount) {
                bestCount = count;
                bestResult = h;
            }
        }
        return bestResult;
    }

    function _distributeRewards(uint256 requestId, bytes32 consensusResult) internal {
        InferenceRequest storage req = requests[requestId];
        WorkerSignal[] storage sigs = signals[requestId];

        uint256 rewardPerWorker = req.stake / MIN_SIGNALS;
        uint256 slashAmount = MIN_STAKE / 10;

        for (uint256 i = 0; i < sigs.length && i < MIN_SIGNALS; i++) {
            if (sigs[i].resultHash == consensusResult) {
                (bool success, ) = payable(sigs[i].worker).call{value: rewardPerWorker}("");
                if (!success) {
                    // Reward stays in contract
                }
            } else {
                // Slash dissenting worker
                if (workerStakes[sigs[i].worker] >= slashAmount) {
                    workerStakes[sigs[i].worker] -= slashAmount;
                    emit WorkerSlashed(sigs[i].worker, slashAmount);
                }
            }
        }
    }

    function getSignalCount(uint256 requestId) external view returns (uint256) {
        return signals[requestId].length;
    }

    receive() external payable {}
}
